'use strict';
import { DEFAULT_CONFIG, validateConfig, acceptTicker } from './rules.mjs';
const $ = id => document.getElementById(id);
const levelNames={R3:'Resistance 3',R2:'Resistance 2',R1:'Immediate resistance',S1:'Immediate support',S2:'Support 2',S3:'Support 3'};
let config=structuredClone(DEFAULT_CONFIG),levels=[];
let editingConfig=null,legacyPaused=false;
try{legacyPaused=localStorage.getItem('etherwatch-armed')==='false'&&!localStorage.getItem('etherwatch-migrated');}catch{}
const state = {price:null,candles:[],days:90,armed:true,events:[],lastSuccess:0,lastCandles:0,busy:false,chartData:[],stats:null,serverReady:false,seen:new Set(),bootstrapped:false};
const usd = n => Number.isFinite(n) ? n.toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}) : '—';
const short = n => Number.isFinite(n) ? '$'+Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:2}).format(n) : '—';
const escapeHTML = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try {state.events=JSON.parse(localStorage.getItem('etherwatch-alerts')||'[]').filter(e=>e&&typeof e.message==='string'&&Number.isFinite(e.time)).slice(0,50);state.armed=localStorage.getItem('etherwatch-armed')!=='false';} catch {}
function persist(){try{localStorage.setItem('etherwatch-alerts',JSON.stringify(state.events));localStorage.setItem('etherwatch-armed',String(state.armed));}catch{}}
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',7000);}
function renderEvents(){ $('alert-count').textContent=state.events.length; if(!state.events.length)return; $('alert-list').innerHTML=state.events.map(e=>`<div class="event">${escapeHTML(e.message)}<small>${escapeHTML(new Date(e.time).toLocaleString())}${e.delivery?' · '+escapeHTML({pending:'Awaiting Codex report',reported:'Reported by Codex',cancelled:'Cancelled after settings change'}[e.delivery]||e.delivery):' · Saved in this browser'}</small></div>`).join(''); }
async function api(path,body){const response=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(18000),cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||'Monitor service unavailable');return data;}
function applyConfig(next){config=validateConfig(next);state.armed=config.armed;levels=Object.entries(levelNames).map(([code,name])=>({code,name,price:config.levels[code]}));$('range-support').textContent=usd(config.levels.S1);$('range-resistance').textContent=usd(config.levels.R1);$('rule-summary').textContent=`${{immediate:'Immediate breach',close:'Completed daily close',retest:'Daily retest'}[config.mode]} · ${config.cooldownMinutes}m cooldown · Saved revision ${config.revision}`;renderArmed();renderLevels();if(state.price)renderPosition(state.price);draw();}
function showMonitor(data,notify=false){state.serverReady=true;if(data.config)applyConfig(data.config);const events=data.events||[];for(const event of events){if(!state.seen.has(event.id)){state.seen.add(event.id);if(notify&&state.bootstrapped&&Date.now()-event.time<120000){toast(event.message);if('Notification' in window&&Notification.permission==='granted'){try{new Notification('Ether Watch · Price alert',{body:event.message,tag:event.id});}catch{}}}}}if(events.length){state.events=[...events,...state.events.filter(old=>!events.some(e=>e.id===old.id||e.time===old.time&&e.message===old.message))].sort((a,b)=>b.time-a.time).slice(0,50);renderEvents();}persist();state.bootstrapped=true;const bg=data.background||{},delayed=bg.lastCheck&&Date.now()-bg.lastCheck>bg.intervalMinutes*120000;$('background-status').textContent=bg.lastError?'Background check failed':bg.enabled?(config.armed?(delayed?'Background check delayed':'Codex monitoring configured'):'Monitoring paused'):'Codex setup pending';$('background-last').textContent=(bg.lastCheck?'Last background check: '+new Date(bg.lastCheck).toLocaleString():'No background check recorded')+(data.lastEvaluatedCandle?' · Daily candle: '+new Date(data.lastEvaluatedCandle*1000).toISOString().slice(0,10):'');$('background-note').textContent=bg.lastError?bg.lastError:bg.enabled?`Checks every ${bg.intervalMinutes} minutes while Codex and this machine are available. Brief breaches between checks can be missed.`:'Saved levels and rules will be used by the Codex monitor once its automation is enabled.';if(data.evaluationError)$('rule-summary').textContent+=' · Evaluation error: '+data.evaluationError;}
async function checkAlert(){if(!state.serverReady)return;try{showMonitor(await api('check',{source:'browser'}),true);}catch(e){$('rule-summary').textContent='Alert evaluation unavailable · '+e.message;}}
function renderPosition(price){const support=config.levels.S1,resistance=config.levels.R1;$('range-pin').style.left=Math.max(0,Math.min(100,(price-support)/(resistance-support)*100))+'%';$('range-note').textContent=price<support?'Below immediate support':price>resistance?'Above immediate resistance':'Within immediate range';$('structure').innerHTML=`<span class="eyebrow">${price<support?'SUPPORT BREACH':price>resistance?'RESISTANCE BREACH':'INSIDE THE WATCH ZONE'}</span><h3>${price<support?'Watching '+usd(config.levels.S2):price>resistance?'Watching '+usd(config.levels.R2):'Between key levels'}</h3><p>ETH is ${Math.abs(price/support*100-100).toFixed(2)}% ${price>=support?'above':'below'} S1 and ${Math.abs(price/resistance*100-100).toFixed(2)}% ${price>=resistance?'above':'below'} R1. Saved levels define your watch zone.</p>`;}
function renderLevels(){ $('level-list').innerHTML=levels.map(l=>`<div class="level ${l.code[0]==='S'?'support':''}"><span class="level-code">${l.code}</span><div><span class="level-name">${l.name}</span><span class="level-price">${usd(l.price)}</span></div><span class="level-distance">${state.price?((l.price/state.price-1)*100>=0?'+':'')+((l.price/state.price-1)*100).toFixed(2)+'%':'—'}</span></div>`).join(''); }
function ema(values,period){const out=Array(values.length).fill(null);if(values.length<period)return out;let v=values.slice(0,period).reduce((a,b)=>a+b,0)/period;out[period-1]=v;for(let i=period;i<values.length;i++){v=values[i]*2/(period+1)+v*(1-2/(period+1));out[i]=v;}return out;}
function rsi(values,period=14){if(values.length<=period)return null;let gain=0,loss=0;for(let i=1;i<=period;i++){const d=values[i]-values[i-1];gain+=Math.max(d,0)/period;loss+=Math.max(-d,0)/period;}for(let i=period+1;i<values.length;i++){const d=values[i]-values[i-1];gain=(gain*(period-1)+Math.max(d,0))/period;loss=(loss*(period-1)+Math.max(-d,0))/period;}return loss===0?(gain===0?50:100):100-100/(1+gain/loss);}
function completed(){return state.candles.filter(c=>c.time+86400<=Date.now()/1000);}
function indicators(){const candles=completed(),closes=candles.map(c=>c.close),strength=rsi(closes);if(strength!==null){$('momentum').textContent=strength.toFixed(1)+' '+(strength>=70?'Overbought':strength<=30?'Oversold':strength>=50?'Bullish':'Bearish');$('momentum').style.fontSize='23px';$('momentum').className='value '+(strength>=50?'positive':'negative');$('rsi-bar').style.width=strength+'%';}const fast=ema(closes,12),slow=ema(closes,26),macd=closes.map((_,i)=>fast[i]!==null&&slow[i]!==null?fast[i]-slow[i]:null).filter(x=>x!==null),signal=ema(macd,9);if(signal.length&&signal.at(-1)!==null){const h=macd.at(-1)-signal.at(-1);$('macd').textContent=(h>=0?'+':'')+h.toFixed(2)+' histogram';$('macd').className=h>=0?'positive':'negative';$('macd').title=`MACD ${macd.at(-1).toFixed(2)} / Signal ${signal.at(-1).toFixed(2)}`;}if(candles.length>20){const avg=candles.slice(-21,-1).reduce((sum,c)=>sum+c.volume,0)/20;$('rvol').textContent=avg>0?(candles.at(-1).volume/avg).toFixed(2)+'× average':'—';}if(closes.length){const series=closes.slice(-30),min=Math.min(...series),max=Math.max(...series);$('spark').setAttribute('d',series.map((v,i)=>`${i?'L':'M'}${i/(series.length-1)*180},${40-(v-min)/(max-min||1)*35}`).join(' '));}}
async function request(path){const response=await fetch('https://api.exchange.coinbase.com/products/ETH-USD/'+path,{signal:AbortSignal.timeout(12000),cache:'no-store'});if(!response.ok)throw new Error('Market feed returned '+response.status);return response.json();}
function updatePrice(ticker,stats){const {price,time}=acceptTicker(ticker,Date.now());state.price=price;state.lastSuccess=Date.now();$('price').textContent=usd(price);$('connection').textContent='● Live · 15s updates';$('connection').style.color='var(--green)';$('updated').textContent='Updated '+new Date(time).toLocaleTimeString()+' · Coinbase';if(stats){const open=Number(stats.open),volume=Number(stats.volume);if(open>0){const change=(price/open-1)*100;$('change').textContent=(change>=0?'↗ +':'↘ ')+change.toFixed(2)+'%';$('change').className=change>=0?'positive':'negative';}if(Number.isFinite(volume))$('volume').textContent=short(volume*price);}renderPosition(price);renderLevels();draw();}
async function refresh(){if(state.busy)return;state.busy=true;$('refresh').disabled=true;const needCandles=Date.now()-state.lastCandles>300000;const results=await Promise.allSettled([request('ticker'),request('stats'),...(needCandles?[request('candles?granularity=86400')]:[])]);if(results[1].status==='fulfilled')state.stats=results[1].value;if(results[0].status==='fulfilled'){try{updatePrice(results[0].value,state.stats);}catch(e){feedError(e.message);}}else feedError(results[0].reason.message);if(needCandles){if(results[2].status==='fulfilled'){const rows=results[2].value;if(Array.isArray(rows)){state.candles=rows.filter(r=>Array.isArray(r)&&r.length>=6&&r.every(Number.isFinite)&&r[1]>0&&r[2]>=r[1]&&r[3]>=r[1]&&r[3]<=r[2]&&r[4]>=r[1]&&r[4]<=r[2]&&r[0]%86400===0&&r[0]<=Date.now()/1000&&r[5]>=0).map(r=>({time:r[0],low:r[1],high:r[2],open:r[3],close:r[4],volume:r[5]})).sort((a,b)=>a.time-b.time);if(state.candles.length){state.lastCandles=Date.now();$('chart-empty').style.display='none';indicators();draw();}else chartError();}else chartError();}else chartError();}state.busy=false;$('refresh').disabled=false;}
function feedError(message){$('connection').textContent=state.lastSuccess?'● Stale · reconnecting':'● Feed unavailable';$('connection').style.color='var(--red)';$('connection').title=message;$('updated').textContent=state.lastSuccess?'Last successful update '+new Date(state.lastSuccess).toLocaleTimeString():'Unable to reach Coinbase · retrying every 15s';}
function chartError(){if(!state.candles.length){$('chart-empty').style.display='flex';$('chart-empty').innerHTML='Daily chart unavailable<small>The data feed may be blocked or temporarily unavailable.</small>';}else{$('updated').textContent+=' · Daily candles stale';}}
function volumeProfile(candles,bins=30){if(!candles.length)return null;const min=Math.min(...candles.map(c=>c.low)),max=Math.max(...candles.map(c=>c.high)),step=(max-min||1)/bins,volumes=Array(bins).fill(0);for(const c of candles){if(c.high===c.low){volumes[Math.min(bins-1,Math.floor((c.close-min)/step))]+=c.volume;continue;}for(let i=0;i<bins;i++){const overlap=Math.max(0,Math.min(c.high,min+(i+1)*step)-Math.max(c.low,min+i*step));volumes[i]+=c.volume*overlap/(c.high-c.low);}}const peak=Math.max(...volumes);return {min,step,volumes,peak,poc:min+(volumes.indexOf(peak)+.5)*step};}
function draw(){const canvas=$('chart'),rect=canvas.getBoundingClientRect(),w=rect.width,h=rect.height,dpr=window.devicePixelRatio||1;canvas.width=w*dpr;canvas.height=h*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const data=state.candles.slice(-state.days);state.chartData=data;if(!data.length)return;const left=9,right=w-70,top=20,bottom=h-76,volumeBottom=h-28;const min=Math.min(...data.map(c=>c.low),...levels.map(l=>l.price),state.price||Infinity)*.985,max=Math.max(...data.map(c=>c.high),...levels.map(l=>l.price),state.price||0)*1.015;const y=p=>top+(max-p)/(max-min)*(bottom-top),step=(right-left)/data.length,x=i=>left+(i+.5)*step;state.geometry={left,right,step};ctx.font='10px DM Sans, sans-serif';ctx.textAlign='left';for(let i=0;i<5;i++){const p=min+(max-min)*i/4,py=y(p);ctx.strokeStyle='#292f32';ctx.beginPath();ctx.moveTo(left,py);ctx.lineTo(right,py);ctx.stroke();ctx.fillStyle='#798589';ctx.fillText(p.toLocaleString('en-US',{maximumFractionDigits:0}),right+10,py+4);}const profile=volumeProfile(data);if(profile&&profile.peak){$('poc').textContent=usd(profile.poc);if($('show-profile').checked){profile.volumes.forEach((v,i)=>{ctx.fillStyle=i===profile.volumes.indexOf(profile.peak)?'#c2ef8359':'#a1aba51c';ctx.fillRect(right-v/profile.peak*(right-left)*.24,y(profile.min+(i+1)*profile.step),v/profile.peak*(right-left)*.24,Math.max(1,y(profile.min+i*profile.step)-y(profile.min+(i+1)*profile.step)-1));});}}for(const l of levels){ctx.strokeStyle=l.code[0]==='S'?'#a9cb6566':'#e78e8766';ctx.setLineDash([4,5]);ctx.beginPath();ctx.moveTo(left,y(l.price));ctx.lineTo(right,y(l.price));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=l.code[0]==='S'?'#b5d58d':'#d59b96';ctx.font='9px DM Sans, sans-serif';ctx.fillText(l.code+' '+l.price,right+5,y(l.price)-4);}const maxVolume=Math.max(...data.map(c=>c.volume))||1;data.forEach((c,i)=>{const color=c.close>=c.open?'#bce58a':'#d88780';ctx.strokeStyle=color;ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x(i),y(c.high));ctx.lineTo(x(i),y(c.low));ctx.stroke();ctx.fillRect(x(i)-Math.max(1,step*.57)/2,y(Math.max(c.open,c.close)),Math.max(1,step*.57),Math.max(1,Math.abs(y(c.open)-y(c.close))));ctx.globalAlpha=.3;ctx.fillRect(x(i)-step*.3,volumeBottom-c.volume/maxVolume*38,step*.6,c.volume/maxVolume*38);ctx.globalAlpha=1;if(i>0&&c.time+86400<=Date.now()/1000){for(const l of levels){if(c.time-data[i-1].time===86400&&((data[i-1].close<=l.price&&c.close>l.price&&l.code[0]==='R')||(data[i-1].close>=l.price&&c.close<l.price&&l.code[0]==='S'))){ctx.fillStyle='#b6abec';ctx.beginPath();ctx.arc(x(i),y(l.price),2.6,0,Math.PI*2);ctx.fill();}}}if(i%Math.max(1,Math.floor(data.length/5))===0){ctx.fillStyle='#798589';ctx.font='9px DM Sans, sans-serif';ctx.fillText(new Date(c.time*1000).toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'}),x(i),h-7);}});if(state.price){ctx.setLineDash([2,3]);ctx.strokeStyle='#edf0ed66';ctx.beginPath();ctx.moveTo(left,y(state.price));ctx.lineTo(right,y(state.price));ctx.stroke();ctx.setLineDash([]);}}
$('chart').addEventListener('pointermove',event=>{if(!state.geometry)return;const rect=$('chart').getBoundingClientRect(),i=Math.floor((event.clientX-rect.left-state.geometry.left)/state.geometry.step),c=state.chartData[i];if(!c){$('tooltip').hidden=true;return;}$('tooltip').hidden=false;$('tooltip').innerHTML=`${new Date(c.time*1000).toISOString().slice(0,10)} UTC${c.time+86400>Date.now()/1000?' · In progress':''}<br>O ${usd(c.open)} · H ${usd(c.high)}<br>L ${usd(c.low)} · C ${usd(c.close)}<br>Volume ${c.volume.toLocaleString('en-US',{maximumFractionDigits:0})} ETH`;});
$('chart').addEventListener('pointerleave',()=>{$('tooltip').hidden=true;});
document.querySelectorAll('[data-days]').forEach(button=>button.addEventListener('click',()=>{state.days=Number(button.dataset.days);document.querySelectorAll('[data-days]').forEach(b=>b.classList.toggle('selected',b===button));draw();}));
$('show-profile').addEventListener('change',draw);$('refresh').addEventListener('click',async()=>{await loadSettings();await refresh();await checkAlert();});
function renderArmed(){$('pause').textContent=state.armed?'Pause alerts':'Resume alerts';$('armed-badge').textContent=state.serverReady?(state.armed?'ARMED':'PAUSED'):'LOADING';$('rule-summary').textContent=`${usd(config.levels.S1)} support / ${usd(config.levels.R1)} resistance · ${{immediate:'Immediate breach',close:'Completed daily close',retest:'Daily retest'}[config.mode]} · ${config.cooldownMinutes}m cooldown${config.mode==='retest'?' · ±'+config.retestTolerance+'% within '+config.retestCandles+' daily candles':''} · Revision ${config.revision} · ${state.armed?'armed':'paused'}`;}
$('pause').addEventListener('click',async()=>{if(!state.serverReady)return toast('Saved settings service is unavailable.');try{showMonitor(await api('config',{...config,armed:!config.armed,expectedRevision:config.revision}));persist();}catch(e){toast(e.message);}});
$('notify').addEventListener('click',async()=>{if(!('Notification' in window)){toast('This browser does not support desktop notifications. In-page alerts remain available.');return;}try{const permission=await Notification.requestPermission();$('notification-note').textContent=permission==='granted'?'Browser notifications enabled. Keep this page open and connected.':'Notifications are not enabled. You can change permission in browser settings; in-page alerts still work.';$('notify').textContent=permission==='granted'?'Notifications enabled':'Enable notifications';}catch{toast('Browser notifications unavailable. In-page alerts remain active.');}});
function fillSettings(){editingConfig=structuredClone(config);for(const [code,value] of Object.entries(editingConfig.levels))$('level-'+code).value=value;$('alert-mode').value=editingConfig.mode;$('cooldown-minutes').value=editingConfig.cooldownMinutes;$('settings-error').textContent='';}
$('settings-open').addEventListener('click',()=>{if(!state.serverReady)return toast('Saved settings service is unavailable. Try Refresh.');fillSettings();$('settings-dialog').showModal();});
$('settings-cancel').addEventListener('click',()=>$('settings-dialog').close());
$('settings-reset').addEventListener('click',()=>{for(const [code,value] of Object.entries(DEFAULT_CONFIG.levels))$('level-'+code).value=value;$('alert-mode').value=DEFAULT_CONFIG.mode;$('cooldown-minutes').value=DEFAULT_CONFIG.cooldownMinutes;$('settings-error').textContent='Defaults are ready. Save to apply.';});
$('settings-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;try{const next=validateConfig({...editingConfig,levels:Object.fromEntries(Object.keys(editingConfig.levels).map(code=>[code,$('level-'+code).value])),mode:$('alert-mode').value,cooldownMinutes:Number($('cooldown-minutes').value)});for(const button of form.querySelectorAll('button'))button.disabled=true;showMonitor(await api('config',{...next,expectedRevision:editingConfig.revision}));$('settings-dialog').close();toast('Levels and alert rule saved.');}catch(e){$('settings-error').textContent=e.message;}finally{for(const button of form.querySelectorAll('button'))button.disabled=false;}});
async function loadSettings(){try{let data=await api('state');if(legacyPaused&&data.config.revision===1)data=await api('config',{...data.config,armed:false,expectedRevision:1});showMonitor(data);legacyPaused=false;try{localStorage.setItem('etherwatch-migrated','1');}catch{}}catch(e){state.serverReady=false;$('armed-badge').textContent='UNAVAILABLE';$('rule-summary').textContent='Saved monitor service unavailable';$('background-status').textContent='Configuration unavailable';$('background-note').textContent='Live chart data remains available. Alert settings could not be loaded.';}}
new ResizeObserver(draw).observe($('chart'));applyConfig(config);renderEvents();loadSettings().then(async()=>{await refresh();await checkAlert();});setInterval(async()=>{await refresh();await checkAlert();},15000);setInterval(()=>{if(state.lastSuccess&&Date.now()-state.lastSuccess>45000)feedError('No recent successful update');},5000);document.addEventListener('visibilitychange',()=>{if(!document.hidden){loadSettings();refresh();}});
